"""Apply the user-approved reader-facing editorial pass to chapters 1–5."""
from pathlib import Path
from bs4 import BeautifulSoup
import json
root=Path(__file__).parent
replacements={
1:{0:['한 시인이 오래 품어 온 이야기를 다시 쓰려 했다. 그는 글 속의 인물들을 떠올리다가, 젊은 날 자신의 글을 처음 들어 주었던 사람들까지 생각하게 되었다. 사랑했던 사람과 친구들, 이제는 곁에 없는 이들에게 먼저 시 한 편을 바치고 싶었다.','다시 펜을 들려니 반가움과 두려움이 함께 밀려왔다. 이야기는 이어 갈 수 있어도, 그때 그 사람들과 그 시절로 돌아갈 수는 없었다.'],1:[('여기서 나타나는 모습은 실제로 돌아온 사람들이 아니라, 시인의 마음속에서 되살아난 기억이다. 헌시는 소중한 사람들에게 바치는 시를 말한다. 이 작품에서는 본격적인 이야기가 시작되기 전에, 지나온 삶과 그때 함께했던 사람들을 돌아본다.','낯익은 얼굴들은 안개 너머가 아니라 그의 기억 속에서 가까워지고 있었다.')],7:[('삶이 미로 같다는 말은, 살아갈 때는 어느 선택이 어디로 이어질지 쉽게 알 수 없다는 뜻이다. 시인도 이별의 이유를 모두 설명할 수는 없었다.','')],14:[('바람이 줄을 울리는 악기를 에올리아 하프라고 한다. 시인은 스스로 완전히 조절할 수 없는 그 소리에서, 기억과 감정에 이끌려 나오는 자신의 노래를 떠올렸다.','에올리아 하프의 줄은 사람의 손 대신 바람에 울렸다. 시인의 노래도 그처럼 뜻밖에 밀려온 기억에 이끌리고 있었다.')],16:[('기억이 현실이 된다는 말은 죽은 사람이 정말 살아났다는 뜻이 아니다. 오래전의 사랑과 우정이 지금의 시인에게 다시 힘을 주기 시작했다는 뜻에 가깝다.','')]},
2:{0:['공연 날짜가 가까워진 극장에서는 무슨 이야기를 어떻게 보여 줄지를 두고 의견이 갈렸다. 객석을 채워야 하는 지배인과 글을 맡은 시인, 무대에서 관객을 만날 희극 배우가 이야기를 나누려 했다.'],16:[('이것은 시인이 정말 신들을 움직인다는 뜻이 아니었다. 인간의 상상력이 얼마나 넓게 나아갈 수 있는지 강조한 표현이었다.','작은 무대에 서 있어도 그의 상상은 신들의 세계까지 뻗어 갔다.')],22:['지배인은 더 기다릴 수 없다는 듯 시인을 재촉했다. 시인이 앞서 말한 상상력과 재능을 이제는 눈앞의 공연으로 보여 달라는 것이었다. 관객을 사로잡을 재미를 독한 음료에 빗댄 것도 그 때문이었다. 사람들의 마음을 단번에 흔들 만큼 강렬한 공연을 원했다.'],23:[('세 사람이 당장 그 길을 떠난다는 뜻은 아니었다. 앞으로 펼쳐질 연극이 인간의 삶뿐 아니라 더 큰 세계까지 다루리라는 예고였다.','무대 장치를 쓰면 사람 사는 세상도, 하늘과 지옥도 눈앞에 펼쳐 보일 수 있었다. 지배인은 그만큼 크고 다채로운 공연을 기대했다.')]},
3:{0:['극장에서는 아직 공연을 준비하고 있었다. 그들이 무대에 올리려는 이야기의 첫 장면은 인간이 사는 땅보다 훨씬 높은 곳에서 시작되었다. 지상에 있는 학자 파우스트는 그곳에서 자기 이름이 오가게 될 줄 몰랐다.'],1:[('극장의 작은 무대에서 이야기가 끝나자, 이번에는 시선이 하늘로 향했다.','별과 구름 너머, 인간의 세상을 내려다보는 천상에 빛이 퍼졌다.'),('별과 구름 사이에 밝은 빛이 퍼져 있었다. 이곳은 인간의 세상을 내려다보며 이야기하는 천상의 자리였다.','그곳에는 세계를 만든 신, 주가 있었다.'),('이들은 천사들 가운데 중요한 역할을 맡은 대천사였다.','이들은 주를 섬기는 천사들 가운데 중요한 역할을 맡은 대천사였다. 세 천사는 지상에서 본 질서와 움직임을 주에게 전하려 했다.')],4:[('그가 말을 건넨 상대는 주였다. 여기서 주는 이 세계를 만든 신을 부르는 말이다.','그는 주에게 인사를 건넸다. 천사들과 같은 자리에 섰어도, 그가 세상을 바라보는 마음은 달랐다.')],7:[('주가 그를 자신의 종이라고 부른 것은, 파우스트가 아직 헤매고 있더라도 그를 향한 믿음을 거두지 않았다는 뜻이었다.','주는 파우스트를 자신의 종이라고 불렀다. 아직 갈 길을 찾지 못한 사람이지만, 진리를 찾으려는 마음까지 버리지는 않으리라 믿고 있었다.')]},
4:{0:[('그는 오랫동안 철학과 법학, 의학을 공부한 학자였다.','천상에서 대화의 주제가 되었던 그 학자는 이 방에서 혼자 밤을 지새우고 있었다. 파우스트는 대학에서 학생들을 가르치며 철학과 법학, 의학을 오래 공부한 사람이었다.')],6:[('파우스트는 노스트라다무스가 쓴 것으로 여기는 이 책에서 길을 찾으려 했다.','노스트라다무스는 별과 예언을 연구한 인물로 알려져 있었다. 파우스트는 그의 이름이 붙은 이 책이라면 평범한 학문으로 찾지 못한 길을 알려 주리라 기대했다.')],11:[('지령은 땅에 속한 정령을 뜻했다.','이 기호가 가리키는 지령은 땅에서 태어나고 자라고 사라지는 생명의 힘을 지닌 정령이었다.')],20:[('찾아온 사람은 파우스트의 연구를 돕는 바그너였다.','찾아온 바그너는 곁에서 공부하며 파우스트의 연구를 돕는 조수였다. 그는 스승의 지식을 존경했고, 기회가 있을 때마다 더 배우고 싶어 했다.')],21:[('그는 사람들의 마음을 움직이는 말하기 기술을 배우고 싶어 했고, 파우스트는 그 관심에 씁쓸한 농담으로 답했다.','그는 목사도 배우처럼 청중을 사로잡는 말하기를 배우면 좋겠다고 말했다. 파우스트는 목사가 배우처럼 남의 눈에 잘 보이는 일에만 신경 쓴다면 그렇겠다고 비꼬았다. 바그너가 묻는 것은 전달 기술이었지만, 파우스트가 걱정하는 것은 말에 진심이 있는가 하는 문제였다.')]},
5:{0:[('그들은 어디로 놀러 갈지 의논했다.','평소에는 작업장에서 일하던 그들은 오늘만큼은 친구들과 나들이를 즐기려고, 어디로 갈지 의논했다.')],3:[('두 하녀 사이에도 작은 다툼이 있었다.','남의 집에서 살림일을 하던 두 하녀도 휴일 나들이를 나왔다. 그런데 만나고 싶은 사람 이야기가 나오자 두 사람의 걸음이 갈렸다.')],4:[('한편 근처의 학생들은 곱게 차려입은 하녀들을 보고 함께 따라가자고 했다.','근처에서는 공부하러 도시로 온 학생 둘이 걸어오고 있었다. 이들도 오늘은 책을 덮고 놀러 나온 길이었다. 한 학생이 곱게 차려입은 하녀들을 보고 친구에게 따라가자고 했다.')],5:[('시민 집안의 아가씨들은','상점이나 재산을 가진 시민 집안의 아가씨들은')],8:[('한 시민은 시장이 자리에 오른 뒤 더 거만해졌다고 말했다.','시장이 도시를 잘 다스려 주기를 바랐던 한 시민은, 새 시장이 자리에 오른 뒤 더 거만해졌다고 말했다.')],9:[('그들 곁에서 거지가 노래를 불렀다.','그들 곁에는 남들이 건네주는 돈과 음식으로 하루를 견디는 거지가 있었다. 그는 지나가는 사람들이 잠시라도 자신을 봐 주기를 바라며 노래를 불렀다.')],12:[('노파는 젊은 아가씨들의 차림을 칭찬하며, 그들이 원하는 것을 이루어 줄 수 있다고 말했다.','아가씨들에게 다가온 노파는 연애 상대를 점쳐 준다며 사람들의 관심을 끄는 여인이었다. 그는 젊은 아가씨들의 차림을 칭찬하며, 원하는 인연을 만나게 해 줄 수 있다고 말을 붙였다.')],14:[('군인들은 높은 성과 도도한 아가씨들을 모두 정복하겠다는 노래를 불렀다.','이번에는 길을 따라 행진하는 군인들의 노래가 가까워졌다. 이들은 전쟁터로 떠나는 일을 힘차게 노래하며 높은 성과 도도한 아가씨들을 모두 정복하겠다고 자랑했다.')],15:[('군인들이 떠나고 파우스트와 바그너의 모습이 이어졌다.','군인들이 멀어진 길에 파우스트와 조수 바그너가 함께 걸어왔다. 어젯밤 같은 서재에서 이야기를 나누었던 두 사람이 이번에는 성문 밖으로 산책을 나온 것이다.')],19:[('보리수 아래에서는 농민들이 노래하며 춤을 추고 있었다.','들에서 농사를 지으며 사는 마을 사람들이 보리수 아래 모여 있었다. 이들도 일손을 놓고 노래와 춤으로 휴일을 즐겼다.')],27:[('늙은 농부가 파우스트에게 다가왔다.','춤판 곁에서 파우스트를 알아본 늙은 농부가 다가왔다. 그는 예전 이 마을에 역병이 돌 때 파우스트와 아버지가 병자들을 찾아다니던 일을 기억하고 있었다.')],30:[('거룩한 성체가 오기라도 하는 듯','교회에서 예수의 몸으로 여기며 공경하는 성체를 모실 때처럼')],39:[('두 사람이 실제로 들어 있다는 말이 아니라, 함께 만족시키기 어려운 욕망을 설명한 비유였다.','하나를 따르면 다른 하나가 아쉬워졌다. 세상에 가까이 가려 할수록 세상을 벗어나고 싶은 마음도 그를 잡아당겼다.')],46:[('실제로 그 일을 시킨 것은 아니었다.','바그너는 개가 사람의 말에 곧잘 반응하는 것을 보고 얼마나 잘 훈련되었을지 짐작했다.')]}}
for ch in range(1,6):
 p=root/f'chapter-{ch:02}.html';s=BeautifulSoup(p.read_text(encoding='utf-8'),'html.parser')
 before_de=[x.get_text() for x in s.select('article pre[lang="de"]')];before_ko=[x.get_text() for x in s.select('article .ko-translation')];images=[x['src'] for x in s.select('article figure img')]
 sections=s.select('article .adaptation-intro,article .adaptation-prose')
 for i,changes in replacements.get(ch,{}).items():
  sec=sections[i];ps=[x for x in sec.find_all('p',recursive=False) if 'voice-label' not in x.get('class',[])]
  if changes and isinstance(changes[0],str):
   for x in ps:x.decompose()
   for j,body in enumerate(changes):
    para=s.new_tag('p');para.string=body
    if sec.select_one('.inner-voice'):sec.select_one('.inner-voice').insert_before(para)
    else:sec.append(para)
  else:
   for old,new in changes:
    for para in ps:
     if old in para.get_text():para.string=para.get_text().replace(old,new)
 for label in s.select('article .voice-label'):
  if label.get_text().startswith('[나레이션:'):label.decompose()
 assert [x.get_text() for x in s.select('article pre[lang="de"]')]==before_de
 assert [x.get_text() for x in s.select('article .ko-translation')]==before_ko
 assert [x['src'] for x in s.select('article figure img')]==images
 p.write_text(str(s),encoding='utf-8')
 data_path=root/f'adaptations/chapter-{ch:02}.json';data=json.loads(data_path.read_text(encoding='utf-8'))
 prose=s.select('article .adaptation-prose')
 for i,sec in enumerate(prose):
  body='\n'.join(x.get_text() for x in sec.find_all('p',recursive=False) if 'voice-label' not in x.get('class',[]))
  if ch==1:data['passages'][i]=body
  else:data['scenes'][i]['narration']=body
 intro=s.select_one('article .adaptation-intro')
 if intro:
  data['reader_introduction_html']=str(intro)
  for key in ('introduction_html','intro_html'):
   if key in data:data[key]=str(intro)
 data['reader_editorial_policy']='나레이션 표제 없이 인물 소개와 발언 맥락을 자연스러운 본문으로 설명. 독백 인물 이름 유지.'
 data_path.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
 print(f'Chapter {ch}: narration labels removed; introductions/context revised; original/translation/images unchanged')
